using System.Windows; using System.Windows.Controls; using AshkanIndustrialOperations.Models; using AshkanIndustrialOperations.Services; namespace AshkanIndustrialOperations.Views; public partial class AlarmsView:UserControl {readonly DemoDataService _d; public AlarmsView(DemoDataService d){InitializeComponent();_d=d;DataContext=d;} void Ack_Click(object s,RoutedEventArgs e){if(Grid.SelectedItem is Alarm a){a.State="Acknowledged";Grid.Items.Refresh();_d.Log("Alarm acknowledged",a.Code+" / "+a.Asset);}} void WorkOrder_Click(object s,RoutedEventArgs e){if(Grid.SelectedItem is Alarm a){var no="WO-"+DateTime.Now.ToString("HHmmss");_d.WorkOrders.Insert(0,new WorkOrder{Number=no,Asset=a.Asset,Type="Corrective",Priority=a.Severity,Assignee="Unassigned",DueDate="Today",Status="Open"});_d.Log("Work order created",no+" from "+a.Code);MessageBox.Show("Work order "+no+" created.","AIOP");}} }